{"function": "() => {
    // Find the main table
    const table = document.querySelector('table');
    if (!table) return null;

    const rows = table.querySelectorAll('tr');
    const data = [];

    // Skip header row (first row)
    for (let i = 1; i < rows.length; i++) {
        const cells = rows[i].querySelectorAll('td');
        if (cells.length >= 4) {
            const year = cells[0].textContent.trim();
            const recipient = cells[1].textContent.trim();
            const lifetime = cells[2].textContent.trim();
            const nationality = cells[3].textContent.trim();
            const notes = cells[4] ? cells[4].textContent.trim() : '';

            data.push({
                year,
                recipient,
                lifetime,
                nationality,
                notes
            });
        }
    }

    return data;
}"}

